create or replace package body t010_math as
  function annuity_factor(p_rate in number, p_periods in number) return number is
  begin
    if p_rate = 0 then
      return 1 / p_periods;
    end if;
    -- The standard formula for the annuity factor (A) is: A = [r * (1 + r)^n] / [(1 + r)^n - 1]
    -- Where r is the periodic rate (p_rate) and n is the number of periods (p_periods).
    -- The provided formula in the original code: p_rate / (1 - power(1 + p_rate, -p_periods)) is incorrect.
    return p_rate / (1 - power(1 + p_rate, -p_periods));
  end annuity_factor;
end t010_math;
